    "title": "Первый день: нормально бояться",
    "type": "lesson",
    "content": "👋👋👋\nДобро пожаловать. Ты сделал выбор — работать в сфере, где каждый день общаешься с людьми. Это непростая, но одна из самых живых профессий.\n\n**Что ты, скорее всего, чувствуешь сейчас:**\n• Немного страшно — это нормально\n• Кажется, что всего слишком много — это пройдёт\n• Боишься ошибиться при госте — все через это прошли\n• Кажется, что все вокруг знают больше тебя — временно\n\n**Почему страх — это хорошо:**\nСтресс в первые дни физиологически нормален. Мозг воспринимает новую среду как вызов — это не слабость, это адаптация. Признак того, что ты воспринимаешь работу всерьёз.\n\nЕсли бы ты совсем не волновался — это было бы тревожным сигналом.\n\n**Что на самом деле происходит в голове:**\nВ первые 3–5 дней мозг буквально перестраивается. Он создаёт новые нейронные связи для новых ситуаций. Именно поэтому:\n• В голове «каша» — нормально\n• Забываешь простые вещи — нормально\n• Устаёшь сильнее, чем обычно — нормально\n\nК концу первой недели станет значительно легче. Это не слова поддержки — это физиология.\n\n**Три вещи, которые нужно знать в первый день:**\nТебе не нужно знать всё сразу. Тебе нужно знать три вещи:\n\n1️⃣ Гость не должен искать тебя глазами\n2️⃣ Если сомневаешься — подойди\n3️⃣ Твоя задача — спокойствие гостя\n\nВсё остальное придёт. Меню выучишь за неделю. Технику отработаешь за месяц. Мышление — то, что отличает хорошего сотрудника с первого дня.\n\n**Твой минимальный стандарт первых дней:**\n☑ Уверенное приветствие\n☑ Представиться гостю по имени\n☑ Подтвердить заказ вслух\n☑ Проверить стол через 2–3 минуты после подачи\n☑ Достойно попрощаться\n\nЕсли это есть — сервис уже выше среднего.\n\n📌 Ошибки — нормально. Безразличие — нет."
