    "id": "s0-4",
    "title": "Shadow и первые шаги",
    "type": "lesson",
    "content": "Обучение идёт по простой формуле:\n\n**ПОКАЗ → ПОВТОР → КОРРЕКЦИЯ → ЗАКРЕПЛЕНИЕ**\n\n**День 1–2: Shadow (смотришь)**\n• Ходишь с наставником — наблюдаешь\n• Не импровизируешь — копируешь поведение\n• Задаёшь вопросы после смены, не в зале\n• Запоминай не слова — а как двигается, как смотрит, как подходит.\n\n**День 3–5: Контролируемая самостоятельность**\n• 1–2 стола под присмотром наставника\n• Право на ошибку — это нормально\n• Наставник рядом — но не мешает.\n\n**День 6–10: Осознанность**\n• Тебя начнут спрашивать, а не учить:\n«Почему ты подошёл именно сейчас?»\n«Что ты увидел у этого стола?»\n\nЕсли можешь ответить — значит, сервис закрепился.\n\n**Что наставник никогда не скажет:**\n🚫 «Разберёшься» — это значит бросил\n🚫 «Смотри, как все делают» — у всех по-разному\n\n**Что наставник скажет:**\n✅ «Как думаешь, что гость почувствовал?»\n✅ «Что бы ты сделал иначе?»\n\n**Если что-то непонятно — три варианта:**\n1. Спроси наставника до смены или после\n2. В зале при необходимости — «одну секунду» и тихо уточни у наставника\n3. Запиши — разберёте вместе после смены\n\n📌 Если что-то непонятно — спрашивай наставника ДО смены или ПОСЛЕ. Не в зале при гостях."
