    "content": "Твоё поведение — это уже 70% сервиса. Гость считывает тебя раньше, чем ты успеешь что-либо сказать.\n\n**Внешний вид:**\n• Чистая форма без пятен и складок\n• Ухоженный вид: волосы, руки, запах\n• Прямая осанка — это уверенность, не армия\n• Спокойный темп движения — не беги, не тащись\n\n**Личная гигиена:**\n• Мой руки после туалета, после касания лица и после работы с деньгами\n• Ногти короткие и чистые\n• Украшения на руках нежелательны при работе с едой\n• Волосы убраны\n• Тарелки держи за края и дно — не касайся рабочей части\n\n**Запрещено категорически:**\n🚫 Телефон в зале — даже «одним глазом»\n🚫 Спешка и суета — это тревога для гостя\n🚫 Личные разговоры с коллегами при гостях\n🚫 Фамильярность: «дорогой», «ребята», «девочки»\n🚫 Жевать, есть, пить в зале\n🚫 Жаргон: «прикольно», «чё», «окей» — говорим «замечательно», «хорошо», «конечно»\n🚫 Уменьшительно-ласкательные слова: «супчик», «рыбка», «говядинка»\n\n**Почему это важно:**\nГость видит тебя весь вечер. Если ты суетишься — он чувствует хаос. Если ты спокоен — он расслабляется."
