    "content": "👣👣👣\nКаждый визит гостя — 9 конкретных шагов.\n\n🦶 1. Встреча — заметить гостя за 10 секунд, тепло, улыбка, гардероб, рассадка, меню\n🦶 2. Знакомство — подойти через минуту, представиться, аперитив\n🦶 3. Аперитив — на подносе, справа правой рукой, называй полное название\n🦶 4. Заказ — помочь с выбором, повторить, поблагодарить. Напитки 3 мин, закуски 10 мин\n🦶 5. Check Back — через несколько минут после подачи: «Как вам блюдо?»\n🦶 6. Следующие блюда — отправлять на кухню за 3–7 минут до того, как гости доедят. Правило 2 пальцев для напитков\n🦶 7. Десерты — убрать грязное с разрешения, предложить открытым вопросом. Правило последнего бокала\n🦶 8. Расчёт — предчек по первой просьбе, сдача за 3 минуты, после расчёта продолжай вести стол\n🦶 9. Прощание — искренняя благодарность, «Ждём вас снова», стол перекрыт за 1 минуту\n\n**Допродажа на шаге «Заказ»:**\n• Up-selling — вариант классом выше: бокал премиального вина вместо домашнего\n• Cross-selling — дополнение к заказу: гарнир, соус, напиток к блюду, десерт\nИ то и другое — рекомендация, а не давление.\n\n📌 9 шагов — это структура. Внутри неё ты живёшь и создаёшь ощущение."
