    "type": "lesson",
    "content": "🛡️🛡️🛡️\nГость почти никогда не злится из-за блюда. Он злится из-за ощущения неуважения.\n\n**Правило L.A.S.T.:**\n\n🔵 **L — LISTEN (слушать)**\n• Не перебивай — даже если гость неправ\n• Не оправдывайся, не ссылайся на кухню\n• Смотри в глаза, держи спокойный голос\n\n🔵 **A — APOLOGIZE (понять и извиниться)**\n• Принеси извинения от ресторана\n• Не обвиняй коллег при госте\n✅ «Я вижу, что вам неприятно»\n🚫 «У нас такого раньше не было»\n\n🔵 **S — SOLVE (немедленно решить)**\n✅ «Я могу заменить блюдо прямо сейчас»\n✅ «Позвольте, я позову менеджера»\n\n🔵 **T — THANK (поблагодарить)**\n• Жалоба — это возможность стать лучше\n• Гости, которые говорят, — помогают вам расти\n\n📌 Фраза, которая работает всегда: «Спасибо, что сказали — сейчас решим»"
