    "type": "lesson",
    "content": "🎭🎭🎭\nНе все конфликтные гости одинаковы. Умение быстро определить тип — ключ к правильной реакции.\n\n**🔴 Агрессивный гость**\nГромко, резко, не слушает. Хочет выплеснуть эмоцию.\n\nТактика:\n• Молчи и слушай — не перебивай\n• Короткие спокойные фразы\n• Не спорь — он не слышит аргументы\n• Немедленно зови менеджера\n✅ «Я понимаю. Сейчас решим»\n\n**🟠 Демонстративный гость**\nКонфликт «на публику» — хочет, чтобы видели другие.\n\nТактика:\n• Внимательный и уважительный тон\n• Предложи перейти в тихое место\n• Не оправдывайся громко\n✅ «Позвольте, обсудим это здесь» (тихо отводишь в сторону)\n\n**🟡 Уставший / раздражённый гость**\nПроблема вне ресторана. Он просто на пределе.\n\nТактика:\n• Максимальная мягкость\n• Быстрый жест доброй воли (вода, комплимент)\n• Не лезь с вопросами\n✅ «Позвольте принести вам воды»\n\n**Что НЕЛЬЗЯ в любом типе конфликта:**\n🚫 Спорить и доказывать, кто прав\n🚫 Ссылаться на кухню или других сотрудников\n🚫 Говорить «Я ничего не могу сделать»\n🚫 Обсуждать конфликт с коллегами при гостях\n\n**Для новичка — главное правило:**\nЕсли сомневаешься, как реагировать, — немедленно зови менеджера. Это не слабость. Это профессионализм.\n\n📌 Даже если гость неправ на 100% — твоя задача не победить в споре, а сохранить его лояльность."
