    "id": "s6-3",
    "title": "Работа с отзывами",
    "type": "lesson",
    "content": "💬💬💬\nОтзыв — это голос гостя после того, как он ушёл. Это последний шанс повлиять на впечатление.\n\n**Типы отзывов:**\n\n🟢 **Положительный отзыв**\n• Поблагодари мысленно — это оценка твоего труда\n• Скажи менеджеру — хорошие отзывы важны для команды\n• Запомни, что понравилось — воспроизводи снова\n\n🔴 **Негативный отзыв**\n• Не защищайся и не обвиняй других\n• Скажи менеджеру сразу\n• Воспринимай как информацию, а не атаку\n\n**Если гость оставляет отзыв прямо в зале:**\n✅ «Спасибо, что сказали — это очень важно для нас»\n✅ «Рад, что вам понравилось — ждём вас снова»\n🚫 «Ну, бывает» — это пренебрежение\n🚫 «Не знаю, это не моя зона» — гость видит только ресторан\n\n**Если гость уходит явно недовольным:**\n• Мягкий финальный контакт: «Надеюсь, всё было хорошо»\n• Немедленно сообщи менеджеру\n\n**Прощание — стандарт:**\n✅ «Спасибо, что выбрали нас. Будем рады видеть вас снова»\n\n📌 Последнее слово — это то, что гость унесёт с собой."
